import { useEffect, useState, type FormEvent } from 'react'
import { createExpense, fetchExpenses, ValidationError, type Expense } from './api'

const fields = ['label', 'amount', 'currency'] as const

export function App() {
  const [expenses, setExpenses] = useState<Expense[]>([])
  const [loading, setLoading] = useState(true)
  const [loadError, setLoadError] = useState<string | null>(null)
  const [label, setLabel] = useState('')
  const [amount, setAmount] = useState('')
  const [currency, setCurrency] = useState('EUR')
  const [errors, setErrors] = useState<Record<string, string>>({})
  const [formError, setFormError] = useState<string | null>(null)
  const [submitting, setSubmitting] = useState(false)

  useEffect(() => {
    const controller = new AbortController()
    fetchExpenses(controller.signal)
      .then(setExpenses)
      .catch((e: unknown) => {
        if (!controller.signal.aborted) setLoadError(e instanceof Error ? e.message : 'Failed to load expenses')
      })
      .finally(() => {
        if (!controller.signal.aborted) setLoading(false)
      })
    return () => controller.abort()
  }, [])

  async function onSubmit(e: FormEvent) {
    e.preventDefault()
    setSubmitting(true)
    setErrors({})
    setFormError(null)
    try {
      const created = await createExpense({ label, amount: Number(amount), currency })
      setExpenses((prev) => [...prev, created])
      setLabel('')
      setAmount('')
    } catch (err) {
      if (err instanceof ValidationError) {
        setErrors(err.errors)
        const extra = Object.values(
          Object.fromEntries(Object.entries(err.errors).filter(([k]) => !(fields as readonly string[]).includes(k))),
        )
        if (extra.length) setFormError(extra.join(' '))
      } else {
        setFormError(err instanceof Error ? err.message : 'Failed to submit expense')
      }
    } finally {
      setSubmitting(false)
    }
  }

  return (
    <main>
      <h1>My expenses</h1>
      {loading && <p>Loading…</p>}
      {loadError && <p role="alert">{loadError}</p>}
      {!loading && !loadError && expenses.length === 0 && <p>No expenses yet.</p>}
      {expenses.length > 0 && (
        <table>
          <thead>
            <tr><th>Label</th><th>Amount</th><th>Status</th></tr>
          </thead>
          <tbody>
            {expenses.map((x) => (
              <tr key={x.id}>
                <td>{x.label}</td>
                <td>{new Intl.NumberFormat(undefined, { style: 'currency', currency: x.currency }).format(x.amount)}</td>
                <td>{x.status}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}

      <h2>Submit an expense</h2>
      <form onSubmit={onSubmit} noValidate>
        <div>
          <label htmlFor="label">Label</label>
          <input id="label" value={label} onChange={(e) => setLabel(e.target.value)}
            aria-invalid={!!errors.label} aria-describedby={errors.label ? 'label-error' : undefined} />
          {errors.label && <span id="label-error" role="alert">{errors.label}</span>}
        </div>
        <div>
          <label htmlFor="amount">Amount</label>
          <input id="amount" type="number" step="0.01" value={amount} onChange={(e) => setAmount(e.target.value)}
            aria-invalid={!!errors.amount} aria-describedby={errors.amount ? 'amount-error' : undefined} />
          {errors.amount && <span id="amount-error" role="alert">{errors.amount}</span>}
        </div>
        <div>
          <label htmlFor="currency">Currency</label>
          <input id="currency" value={currency} onChange={(e) => setCurrency(e.target.value)}
            aria-invalid={!!errors.currency} aria-describedby={errors.currency ? 'currency-error' : undefined} />
          {errors.currency && <span id="currency-error" role="alert">{errors.currency}</span>}
        </div>
        {formError && <p role="alert">{formError}</p>}
        <button type="submit" disabled={submitting}>{submitting ? 'Submitting…' : 'Submit'}</button>
      </form>
    </main>
  )
}
